<script setup lang="ts">
import { reviewTerm, reviewModelName, readableChineseText } from '@/utils/reviewPresentation'
import { nextTick, ref, watch } from 'vue'
import { useLessonReviewStore } from '@/stores/lessonReview'
import { formatReviewTime } from '@/utils/lessonReview'
import AppIcon from '@/components/common/AppIcon.vue'
const emit = defineEmits<{ citation: [] }>()
const store = useLessonReviewStore()
function seekCitation(time: number) { store.seek(time); emit('citation') }
const query = ref('')
const chat = ref<HTMLElement | null>(null)
const prompts = ['What are the main topics of this lesson? Please cite lesson evidence.', 'What is being discussed in this segment, and how does it relate to the courseware?']
async function send(text = query.value) { if (!text.trim() || store.isThinking) return; query.value = ''; await store.ask(text) }
watch(() => store.messages.map(m => m.status).join(','), async () => { await nextTick(); if (chat.value) chat.value.scrollTop = chat.value.scrollHeight })
</script>
<template>
  <section id="assistant" class="panel review-assistant">
    <div class="assistant-title"><span><AppIcon name="spark" :size="21" /></span><div><h2>Review this lesson together</h2><p>Ground answers in lesson evidence</p></div><i></i></div>
    <div class="assistant-source-note">Generated by the configured model · Sources and citations appear with each answer</div>
    <div class="assistant-scope"><span>Question scope</span><div role="group" aria-label="Question scope"><button :class="{ active: store.scope === 'lesson' }" :disabled="store.isThinking" @click="store.scope = 'lesson'">Whole lesson</button><button :class="{ active: store.scope === 'current' }" :disabled="store.isThinking" @click="store.scope = 'current'">Current segment</button></div><small>{{ store.scope === 'current' ? store.timeText : store.durationText }}</small></div>
    <div ref="chat" class="review-chat" role="log" aria-live="polite" aria-relevant="additions text">
      <div v-if="!store.messages.length" class="chat-welcome"><h3>Start with a question about the lesson</h3><p>Use audio, courseware and concept relationships to explore the content. Citations link back to the original video.</p><button v-for="(prompt, i) in prompts" :key="prompt" @click="store.scope = i ? 'current' : 'lesson'; send(prompt)">{{ prompt }}<AppIcon name="arrow" :size="13" /></button></div>
      <article v-for="message in store.messages" :key="message.id" class="review-message"><div class="message-query"><span>You · {{ message.scope === 'lesson' ? 'Whole lesson' : `Current segment ${formatReviewTime(message.at_sec)}` }}</span><p>{{ message.query }}</p></div><div v-if="message.status === 'pending'" class="model-pending" role="status"><i></i>Retrieving lesson evidence and waiting for the model…</div><div v-else-if="message.status === 'error'" class="model-error" role="alert"><strong>No answer was generated</strong><p>{{ message.error }}</p><button class="btn" :disabled="store.isThinking" @click="store.retry(message.id)">Retry this question</button></div><div v-else-if="message.response" class="model-answer"><div class="answer-source"><span>{{ message.response.source === 'local_llm' ? 'Local model' : 'Remote model' }}</span><b>{{ reviewModelName(message.response.model) }}</b></div><p v-for="warning in message.response.warnings || []" :key="warning" class="answer-warning" role="note">{{ warning }}</p><p class="answer-text">{{ message.response.answer }}</p><div class="answer-citations"><button v-for="citation in message.response.citations" :key="citation.id" :title="citation.text" @click="seekCitation(citation.start_sec)"><span>{{ citation.id }} · {{ reviewTerm(citation.kind) }}</span><b>{{ formatReviewTime(citation.start_sec) }}–{{ formatReviewTime(citation.end_sec) }}</b><p>{{ citation.kind === 'slide' ? (readableChineseText(citation.text) || 'Check the original slide image to verify the text.') : citation.text }}</p><small>Review evidence →</small></button><p v-if="!message.response.citations.length" class="no-citations">This answer returned no seekable citations. Check it against the original lesson materials.</p></div><small class="request-id">Request {{ message.response.request_id }}</small></div></article>
    </div>
    <form class="review-chat-form" @submit.prevent="send()"><textarea v-model="query" rows="2" maxlength="2000" aria-label="Ask the review assistant" placeholder="What would you like to know about this lesson?" :disabled="store.isThinking" @keydown.enter.exact.prevent="send()"></textarea><button type="submit" class="send-button" :disabled="store.isThinking || !query.trim()" aria-label="Send lesson question"><AppIcon name="send" :size="17" /></button></form><p class="assistant-footnote">Generated from this lesson’s materials; Model answers still need verification.<br />Retry if the service fails. No substitute answer is generated.</p>
  </section>
</template>
<style scoped>
