olor:#5977a0}.model-pending i{margin-top:6px;width:5px;height:5px;border-radius:50%;background:#567cb2;animation:breath 1.8s ease-in-out infinite}.model-error{margin-top:15px;background:#e2ecf9;color:#4472b3;border:1px solid #c1d5f2;padding:13px;border-radius:6px}.model-error strong{font-size:11px;font-weight:500}.model-error p{font-size:11px;line-height:1.8;margin-top:7px;overflow-wrap:anywhere}.model-error .btn{font-size:10px;padding:7px 9px;margin-top:10px}.answer-source{display:flex;flex-wrap:wrap;gap:6px;margin-top:15px;font-size:8px;align-items:center;color:#5577a7}.answer-source>span{background:#e0eaf9;border-radius:3px;padding:4px 5px;white-space:nowrap}.answer-source b{font-weight:400;overflow-wrap:anywhere}.answer-text{font-size:12px;line-height:2;color:#496387;white-space:pre-wrap;margin:10px 0 12px;overflow-wrap:anywhere}.answer-citations{display:grid;gap:7px}.answer-citations>button{padding:10px 11px;text-align:left;background:#ebf2fb;border:1px solid #cfdff6;border-radius:6px}.answer-citations>button>span{font-size:8px;color:#5a7baa}.answer-citations b{float:right;font-size:9px;color:#496894;font-weight:500}.answer-citations p{font-size:10px;color:#54719a;line-height:1.8;max-height:58px;overflow:hidden;margin:6px 0}.answer-citations small{font-size:8px;color:#5277ac}.answer-citations .no-citations{font-size:10px;color:#446da6}.request-id{display:block;font-size:8px;color:#5b7ca9;margin-top:9px;overflow-wrap:anywhere}.review-chat-form{margin:0 17px;padding:10px;display:flex;gap:7px;align-items:flex-end;border:1px solid #d2ddec;border-radius:8px;background:var(--surface)}.review-chat-form:focus-within{border-color:#7897c3}.review-chat-form textarea{min-width:0;flex:1;resize:vertical;max-height:180px;min-height:45px;border:0;background:none;outline:none;font-size:11px;line-height:1.8;color:#445b7b}.review-chat-form textarea::placeholder{color:#607ca4}.send-button{width:29px;height:29px;border-radius:6px;background:var(--navy);color:white;display:grid;place-items:center;flex-shrink:0}.assistant-footnote{text-align:center;padding:12px 15px 18px;font-size:8px;color:#5e7ca6;line-height:1.9}@keyframes breath{50%{opacity:.25}}
.answer-warning{margin-top:11px;padding:11px 12px;border:1px solid #9cbdec;border-radius:6px;background:#e5eefa;color:#22559d;font-size:11px;line-height:1.85}
</style>
